 ['Printed listings as typeset: the call-out markers sit inside the code', '\nimport re\nstep2 = """for row in range(2, sheet.max_row + 1):\n    state  = sheet[\'B\' + str(row)].value\n    county = sheet[\'C\' + str(row)].value\n    pop    = sheet[\'D\' + str(row)].value\n  ❶ county_data.setdefault(state, {})\n    county_data[state].setdefault(county, {\'tracts\': 0, \'pop\': 0})\n"""\nstep1 = """❶ import openpyxl, pprint\nwb = openpyxl.load_workbook(\'censuspopdata.xlsx\')\n"""\nfor name, text in ((\'Project 9 Step 1\', step1), (\'Project 9 Step 2\', step2)):\n    for how, f in ((\'as printed\', lambda t: t), (\'marker removed\', lambda t: re.sub(\'[❶-❿]\', \'\', t)), (\'marker and one space removed\', lambda t: re.sub(\'[❶-❿] \', \'\', t)), (\'marker replaced by one space\', lambda t: re.sub(\'[❶-❿]\', \' \', t))):\n        try: compile(f(text), \'listing\', \'exec\'); print(name, how, \'compiles\')\n        except (SyntaxError, IndentationError) as e: print(name, how, type(e).__name__, e.msg)\nprint(repr(step2.splitlines()[4][:6]))\n', "Project 9 Step 1 as printed SyntaxError invalid character '❶' (U+2776)\nProject 9 Step 1 marker removed IndentationError unexpected indent\nProject 9 Step 1 marker and one space removed compiles\nProject 9 Step 1 marker replaced by one space IndentationError unexpected indent\nProject 9 Step 2 as printed IndentationError unindent does not match any outer indentation level\nProject 9 Step 2 marker removed IndentationError unindent does not match any outer indentation level\nProject 9 Step 2 marker and one space removed IndentationError unindent does not match any outer indentation level\nProject 9 Step 2 marker replaced by one space compiles\n'  ❶ co'"],
